<template><div class="main-content"><breadcumb :page="order?order.number:'Purchase Order'" folder="Procurement"/><div v-if="order"><div class="d-flex flex-wrap mb-3"><b-button v-if="order.status==='draft'&&can('purchase_orders_issue')" variant="success" class="mr-2" @click="issue">Issue PO</b-button><router-link v-if="order.status==='draft'&&can('purchase_orders_edit_draft')" class="btn btn-outline-primary mr-2" :to="'/app/procurement/purchase-orders/'+order.id+'/edit'">Edit</router-link><b-button class="mr-2" variant="outline-secondary" @click="downloadPdf">Download PDF</b-button><router-link v-if="order.status!=='draft'&&order.status!=='cancelled'&&can('gate_passes_create')" class="btn btn-primary" :to="'/app/procurement/purchase-orders/'+order.id+'/gate-pass'">Record Gate Pass</router-link></div>
<b-row><b-col md="4"><b-card><h5>{{order.provider.name}}</h5><p>{{order.supplier_contact_snapshot}}</p><p><strong>Destination:</strong> {{order.warehouse.name}}</p><span class="badge badge-light-primary">{{label(order.status)}}</span></b-card></b-col><b-col md="8"><b-row><b-col cols="6" md="3" v-for="c in cards" :key="c.key"><b-card class="text-center mb-2"><div class="text-muted">{{c.label}}</div><h4>{{progress.totals[c.key]}}</h4></b-card></b-col></b-row></b-col></b-row>
<b-card class="mt-3" title="Quantity progress"><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Product</th><th>Model</th><th>Ordered</th><th>Received</th><th>Rejected</th><th>Remaining</th><th>Invoiced</th><th>Not invoiced</th><th>Posted</th></tr></thead><tbody><tr v-for="l in progress.lines" :key="l.purchase_order_item_id"><td>{{l.product}}</td><td>{{l.model||'—'}}</td><td>{{l.ordered}}</td><td>{{l.received}}</td><td>{{l.rejected}}</td><td>{{l.remaining}}</td><td>{{l.invoiced}}</td><td>{{l.not_invoiced}}</td><td>{{l.purchased}}</td></tr></tbody></table></div></b-card>
<b-row><b-col md="6"><b-card class="mt-3" title="Gate Passes"><div v-for="g in order.gate_passes" :key="g.id"><router-link :to="'/app/procurement/gate-passes/'+g.id">{{g.number}}</router-link> · {{label(g.status)}}</div></b-card></b-col><b-col md="6"><b-card class="mt-3" title="Supplier Invoices"><div v-for="i in order.supplier_invoices" :key="i.id"><router-link :to="'/app/procurement/supplier-invoices/'+i.id">{{i.supplier_invoice_number}}</router-link> · {{label(i.status)}}</div></b-card></b-col></b-row>
<b-card class="mt-3" title="Timeline"><div class="border-left pl-3 py-2" v-for="a in order.audits" :key="a.id"><strong>{{label(a.action)}}</strong> · {{a.reference}}<br><small>{{a.created_at}} · {{a.user?(a.user.firstname+' '+a.user.lastname):'System'}}</small><p v-if="a.notes">{{a.notes}}</p></div></b-card></div></div></template>
<script>import{mapGetters}from'vuex';export default{data:()=>({order:null,progress:{totals:{},lines:[]},api:'/api/'}),computed:{...mapGetters(['currentUserPermissions']),cards(){return[{key:'ordered',label:'Ordered'},{key:'received',label:'Received'},{key:'remaining',label:'Remaining'},{key:'invoiced',label:'Invoiced'},{key:'not_invoiced',label:'Uninvoiced'},{key:'purchased',label:'Posted'},{key:'order_value',label:'PO value'},{key:'invoiced_value',label:'Invoice value'}]}},mounted(){this.load()},methods:{can(p){return(this.currentUserPermissions||[]).includes(p)},label(v){return String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())},load(){axios.get('procurement/purchase-orders/'+this.$route.params.id).then(r=>{this.order=r.data.purchase_order;this.progress=r.data.progress})},issue(){axios.post('procurement/purchase-orders/'+this.order.id+'/issue').then(this.load)},downloadPdf(){axios.get('procurement/purchase-orders/'+this.order.id+'/pdf',{responseType:'blob'}).then(r=>{let u=URL.createObjectURL(r.data),a=document.createElement('a');a.href=u;a.download=this.order.number+'.pdf';a.click();URL.revokeObjectURL(u)})}}}</script>
